import fs from 'node:fs';
import crypto from 'node:crypto';
import { optimizeModel as baseline } from './baseline.mjs';
import { optimizeModel as candidate } from './candidate.mjs';
import { BoxGeometry, SphereGeometry } from 'three';
const definitions = [ ['box',new BoxGeometry(1,1,1,166,166,166),false], ['curved-color',new SphereGeometry(1,160,100),true] ];
const fixtures = definitions.map(([name,geometry,colored]) => {
 const triangles=geometry.toNonIndexed(); geometry.dispose();
 const positions=triangles.getAttribute('position').array, normals=triangles.getAttribute('normal').array;
 const colors=colored?Float32Array.from(positions,(_v,i)=>(i%13)/12):undefined;
 const mesh={name,positions,normals,colors,groups:[]};
 for(const key of ['positions','normals','colors'])if(mesh[key])fs.writeFileSync(`./${name}-${key}.bin`,Buffer.from(mesh[key].buffer));
