});
const signature = model => {
 const hash=crypto.createHash('sha256');
 for(const mesh of model.meshes)for(const key of ['positions','normals','colors','indices'])if(mesh[key])hash.update(Buffer.from(mesh[key].buffer,mesh[key].byteOffset,mesh[key].byteLength));
