};
const results=[];
for(const {name,model} of fixtures) {
 for(let i=0;i<4;i++){baseline(model,Infinity);candidate(model,Infinity);}
 const rows=[];
 for(let pair=0;pair<12;pair++) {
  const row={pair};
  for(const [label,run]of pair%2?[['candidate',candidate],['baseline',baseline]]:[['baseline',baseline],['candidate',candidate]]) {
   const start=performance.now(), result=run(model,Infinity);
   row[label]=performance.now()-start;row[`${label}Signature`]=signature(result);
  }
  if(row.baselineSignature!==row.candidateSignature)throw Error('Output differs');rows.push(row);
 }
 const median=key=>{const times=rows.map(row=>row[key]).sort((a,b)=>a-b);return (times[5]+times[6])/2;};
 results.push({name,vertices:model.meshes[0].positions.length/3,warmupPairs:4,pairs:12,baselineMedianMs:median('baseline'),candidateMedianMs:median('candidate'),rows});
}
fs.writeFileSync('./results.json',JSON.stringify(results,null,2));
console.log(JSON.stringify(results.map(({rows,...summary})=>summary),null,2));

